"""Operator algebras: commutants, Lie algebras generated by operators, abelian subalgebras, accessibility.

The routines work with operators whose coefficients are numbers. Linear systems are solved exactly, so that the
results stay readable (``I1z + I2z`` and not a floating-point mixture); floating-point coefficients are turned
into rational numbers first. A result is a list of operators that spans a space; the list itself is one basis
of that space among many.

Author: Alexej Jerschow.
"""

from __future__ import annotations

from collections.abc import Sequence
from typing import Any

import numpy as np
import sympy as sp
from sympy.polys.matrices import DomainMatrix

from spyndynamica.liouville import OperatorBasis, default_operator_basis
from spyndynamica.operators import Operator

TOLERANCE = 1e-9


def _as_list(operators: Any) -> list[Operator]:
    out = [operators] if isinstance(operators, Operator) else list(operators)
    if not out or not all(isinstance(op, Operator) for op in out):
        raise TypeError("expected an operator or a list of operators.")
    if any(op.system is not out[0].system for op in out):
        raise ValueError("the operators belong to different spin systems.")
    for op in out:
        if any(sp.sympify(c).free_symbols for c in op.terms.values()):
            raise ValueError("the coefficients of the operators must be numbers.")
    return out


def _flat(matrix: sp.Matrix) -> sp.Matrix:
    """A matrix as a column, row after row."""
    return sp.Matrix(list(matrix))


def _number(vector: Any) -> np.ndarray:
    return np.array(sp.N(sp.Matrix(vector), 30).tolist(), dtype=complex).reshape(-1)


def _matrix(operator: Operator) -> sp.Matrix:
    """The exact matrix of an operator; floating-point coefficients become rational numbers."""
    matrix = operator.matrix()
    if matrix.has(sp.Float):
        matrix = matrix.applyfunc(lambda x: sp.nsimplify(x, rational=True))
    return matrix


def _nullspace(matrix: sp.Matrix) -> list[sp.Matrix]:
    """A basis of the null space of an exact matrix."""
    vectors = DomainMatrix.from_Matrix(matrix).to_field().nullspace().to_Matrix()
    return [vectors[k, :].T for k in range(vectors.rows)]


def _scaled(operator: Operator) -> Operator:
    """The operator divided by its largest coefficient, for a readable result."""
    if not operator.terms:
        return operator
    largest = max(operator.terms.values(), key=lambda c: abs(complex(sp.N(c))))
    return (operator / largest).map_coefficients(sp.radsimp)


class _Span:
    """A growing set of linearly independent vectors, over the complex or over the real numbers."""

    def __init__(self, real: bool = False):
        self.real = real
        self.basis: list[np.ndarray] = []

    def _vector(self, matrix: sp.Matrix) -> np.ndarray:
        v = _number(matrix)
        return np.concatenate([v.real, v.imag]) if self.real else v

    def residual(self, matrix: sp.Matrix) -> float:
        """The norm of the part of the vector outside the span, relative to its own norm."""
        v = self._vector(matrix)
        norm = np.linalg.norm(v)
        if norm == 0:
            return 0.0
        v = v / norm
        for _ in range(2):  # twice, against rounding
            for b in self.basis:
                v = v - np.vdot(b, v) * b
        return float(np.linalg.norm(v))

    def add(self, matrix: sp.Matrix) -> bool:
        """Take the vector in if it is independent of the others; say whether it was."""
        v = self._vector(matrix)
        norm = np.linalg.norm(v)
        if norm == 0:
            return False
        v = v / norm
        for _ in range(2):
            for b in self.basis:
                v = v - np.vdot(b, v) * b
        rest = np.linalg.norm(v)
        if rest < TOLERANCE:
            return False
        self.basis.append(v / rest)
        return True


def _commutator(a: sp.Matrix, b: sp.Matrix) -> sp.Matrix:
    return a * b - b * a


def commutant(operators: Any, within: Sequence[Operator] | None = None, *, basis: OperatorBasis | None = None):
    """Operators that span everything that commutes with all of ``operators`` (SpinDynamica's ``Commutant``).

    Without ``within`` the whole operator space is searched, and the result is written in the operator basis
    ``basis`` (default: the default operator basis of the spin system). With ``within``, a list of operators,
    only their linear combinations are considered (``Commutant[{operators, within}]``).
    """
    operators = _as_list(operators)
    system = operators[0].system
    candidates = list(within) if within is not None else list((basis or default_operator_basis(system)).operators)
    matrices = [_matrix(op) for op in candidates]
    rows = []
    for q in (_matrix(op) for op in operators):
        rows.append(sp.Matrix.hstack(*(_flat(_commutator(q, b)) for b in matrices)))
    out = []
    for coefficients in _nullspace(sp.Matrix.vstack(*rows)):
        total = system.zero()
        for c, b in zip(coefficients, candidates):
            if c != 0:
                total = total + c * b
        out.append(_scaled(total))
    return out


def bicommutant(operators: Any, *, basis: OperatorBasis | None = None) -> list[Operator]:
    """The commutant of the commutant of ``operators`` (SpinDynamica's ``Bicommutant``): the algebra they
    generate together with the unity operator."""
    return commutant(commutant(operators, basis=basis), basis=basis)


def _closure(start: list[sp.Matrix], generators: list[sp.Matrix], real: bool) -> list[sp.Matrix]:
    """``start`` extended by the commutators ``−i[g, a]`` with the generators until nothing new appears."""
    span = _Span(real)
    found = [a for a in start if span.add(_flat(a))]
    fresh = list(found)
    while fresh:
        new = []
        for g in generators:
            for a in fresh:
                c = -sp.I * _commutator(g, a)
                if span.add(_flat(c)):
                    new.append(c)
        found += new
        fresh = new
    return found


def lie_algebra(operators: Any, *, field: str = "R") -> list[Operator]:
    """A basis of the Lie algebra generated by ``operators`` under ``−i[A, B]`` (SpinDynamica's ``LieAlgebra``).

    The generators come first (those that are linearly independent), then the commutators in the order in
    which they are found. ``field='R'`` (the default) counts linear independence over the real numbers, as
    befits Hermitian generators; ``field='C'`` over the complex numbers. The generators must be traceless.
    """
    operators = _as_list(operators)
    if field not in ("R", "C"):
        raise ValueError("field is 'R' or 'C'.")
    if any(op.trace() != 0 for op in operators):
        raise ValueError("the generators of a Lie algebra must be traceless.")
    system = operators[0].system
    span = _Span(field == "R")
    found = [m for m in (_matrix(op) for op in operators) if span.add(_flat(m))]
    fresh = list(found)
    first = True
    while fresh:
        new = []
        # the first round takes every pair of generators once, later rounds everything with the new ones
        pairs = (
            [(a, b) for i, a in enumerate(found) for b in found[i:]]
            if first
            else [(a, b) for a in found for b in fresh]
        )
        first = False
        for a, b in pairs:
            c = -sp.I * _commutator(a, b)
            if span.add(_flat(c)):
                new.append(c)
        found += new
        fresh = new
    return [system.from_matrix(m) for m in found]


def inaccessible(source: Operator, targets: Any, hamiltonians: Any):
    """Whether ``targets`` cannot be reached from ``source`` by evolution under any sequence of the
    ``hamiltonians`` (SpinDynamica's ``InaccessibleOperatorQ``).

    The operators that ``source`` can turn into span ``source`` and its repeated commutators with the
    Hamiltonians. A target is inaccessible when it is orthogonal to all of them. The result is a truth value
    for one target and a list for a list of targets.
    """
    single = isinstance(targets, Operator)
    wanted = _as_list(targets)
    generators = [_matrix(op) for op in _as_list(hamiltonians)]
    _as_list([source, *wanted])
    reached = [_number(_flat(m)) for m in _closure([_matrix(source)], generators, real=False)]
    out = []
    for target in wanted:
        t = _number(_flat(target.matrix()))
        scale = np.linalg.norm(t) or 1.0
        out.append(all(abs(np.vdot(r, t)) < TOLERANCE * scale * (np.linalg.norm(r) or 1.0) for r in reached))
    return out[0] if single else out


def _commute(matrices: Sequence[sp.Matrix]) -> bool:
    for i, a in enumerate(matrices):
        for b in matrices[i + 1 :]:
            if np.abs(_number(_flat(_commutator(a, b)))).max(initial=0.0) > TOLERANCE:
                return False
    return True


def abelian_subalgebra(operators: Any, within: Sequence[Operator] | None = None, *, basis: OperatorBasis | None = None):
    """Commuting Hermitian ``operators`` extended to a maximal set of commuting Hermitian operators
    (SpinDynamica's ``AbelianSubalgebra``).

    The given operators come first; operators that commute with all the ones before are added until none is
    left. The search is over the whole operator space, or over the combinations of ``within``. The unity
    operator is left out, and its part is removed from the operators that are added.
    """
    operators = _as_list(operators)
    system = operators[0].system
    if not _commute([op.matrix() for op in operators]):
        raise ValueError("the operators do not commute with each other.")
    if any((op - op.dagger()).simplify() for op in operators):
        raise ValueError("the operators must be Hermitian.")
    unity = system.unity()
    span = _Span(real=False)
    span.add(_flat(unity.matrix()))
    out = []
    for op in operators:
        if span.add(_flat(op.matrix())):
            out.append(op)
    while True:
        for candidate in commutant(out or [unity], within, basis=basis):
            parts = (candidate + candidate.dagger(), sp.I * (candidate - candidate.dagger()))
            chosen = next((part for part in parts if span.residual(_flat(part.matrix())) > TOLERANCE), None)
            if chosen is not None:
                break
        else:
            return out
        chosen = _scaled((chosen - chosen.projection(unity)).simplify())
        span.add(_flat(chosen.matrix()))
        out.append(chosen)


def is_maximal_abelian(operators: Any, within: Sequence[Operator] | None = None) -> bool:
    """Whether commuting operators are a maximal abelian set: nothing outside their span (and the unity
    operator) commutes with all of them (SpinDynamica's ``MaximalAbelianQ``).

    With ``within`` the question is asked inside the span of those operators.
    """
    operators = _as_list(operators)
    if not _commute([op.matrix() for op in operators]):
        return False
    span = _Span(real=False)
    if within is None:
        span.add(_flat(operators[0].system.unity().matrix()))
    for op in operators:
        span.add(_flat(op.matrix()))
    return all(span.residual(_flat(c.matrix())) < TOLERANCE for c in commutant(operators, within))


__all__ = ["abelian_subalgebra", "bicommutant", "commutant", "inaccessible", "is_maximal_abelian", "lie_algebra"]
